        // 模型二：本地 vLLM（OpenAI 兼容）
        ModelApiConfig vllm = ModelApiConfig.builder()
                .alias("local-vllm")
                .providerName("vllm")
                .apiModelName("Qwen2.5-7B-Instruct")
                .apiHost("http://127.0.0.1:8000")
                .apiEndpoint("/v1/chat/completions")
                .apiKey("sk-local")
                .samplingTemperature(0.7)
                .customParams("{\"repetition_penalty\":1.05}")
                .build();

        List<ModelApiConfig> models = new ArrayList<>();
        models.add(deepseek);
        models.add(vllm);

        GlobalConfigManager decl = rt.declaration();
        decl.setModels(models);

        AgentConfig agentConfig = new AgentConfig();
        agentConfig.setDefaultModel("deepseek-v3");
        decl.setAgentConfig(agentConfig);

        // 应用：两个模型注册进运行时，defaultModel 生效
        decl.applyAllInstance();
        System.out.println("可用模型 = " + rt.modelRegistry().chatAliases());

        // 第一次对话：用默认模型
        AgentContextHolder h1 = AgentContextHolder.builder()
                .userId("u1")
                .historyId(IdGen.uuid())
                .runtime(rt)
                .modelAlias("deepseek-v3")
                .prompt("你是一个严谨的助手")
                .build();
        String a1 = new AutoAgent(h1).chat("用一句话解释什么是向量数据库");
        System.out.println("deepseek 回答 = " + a1);

        // 第二次对话：临时换成本地模型
        AgentContextHolder h2 = AgentContextHolder.builder()
                .userId("u1")
                .historyId(IdGen.uuid())
                .runtime(rt)
                .modelAlias("local-vllm")
                .prompt("你是一个严谨的助手")
                .build();
        String a2 = new AutoAgent(h2).chat("再换个说法解释一遍");
        System.out.println("vllm 回答 = " + a2);

        rt.close();
    }
}

跑起来会看到什么

应用配置时日志出现两条 注册对话模型: deepseek-v3、注册对话模型: local-vllm。

控制台：

可用模型 = [deepseek-v3, local-vllm]
deepseek 回答 = 向量数据库是把文本、图片等转成向量...
vllm 回答 = 可将其想象为一个按"语义距离"排序的仓库...

两次对话走的是两个不同的模型：第一次是 deepseek-v3，第二次是 local-vllm，因为两次 AgentContextHolder 的 modelAlias 不同。

换个场景怎么改

场景一：接入任何 OpenAI 兼容服务

要改的点	怎么填
apiHost	服务根地址，如 https://api.openai.com
apiEndpoint	/v1/chat/completions
apiKey	对应的 key，多数服务走 Bearer 头
apiModelName	服务方要求的模型名，如 gpt-4o-mini

填好这些字段即可使用，因为内核默认按 OpenAI 兼容格式发请求。

场景二：格式非 OpenAI 兼容

内核装配请求参数的逻辑集中在 AgentRequestParamsFactory：

AgentRequestParamsFactory.build(model, enableThinking) 按一条模型配置构造出请求参数（ApiRequestParams）：思考模式 → 采样 → customParams，后写的覆盖先写的。

大多数"格式差异"其实只是多几个私有字段，这类用 customParams 直接透传就能解决。

如果差异大到要改请求体的结构，用 IApiReqParamsCallback 这个扩展接口——它只有一个方法 callback(ApiRequestParams apiRequestParams)，提供一次"拿到即将发出的参数、就地改它"的机会。它的具体挂载由调用链决定。

场景三：控制采样与思考参数

模型上的采样与思考字段经 AgentRequestParamsFactory 装配进 ApiRequestParams。一次对话使用 AgentContextHolder.requestParams，因此要使某次请求带上这些参数，需按模型装配后再置入：

import net.itzq.mira.modules.ai.client.config.AgentRequestParamsFactory;
import net.itzq.mira.modules.ai.client.config.ModelApiConfig;
import net.itzq.mira.modules.ai.client.handle.ApiRequestParams;

ModelApiConfig model = rt.declaration().getModels().get(0);
ApiRequestParams params = AgentRequestParamsFactory.build(model, Boolean.TRUE); // 打开思考
holder.setRequestParams(params);

场景四：换模型

粒度	怎么改
改全局默认	agentConfig.setDefaultModel("local-vllm") 再 applyAllInstance()；或直接 rt.modelRegistry().setDefaultModel("local-vllm")
改这一次	holder.setModelAlias("local-vllm")（构造时写 .modelAlias(...)）
编排节点里改	用 Invocation.modelAlias，见调用参数：这一次怎么跑

注意事项

alias 必须非空：注册时 alias 为空的记录会被跳过并打日志。

null 不等于默认值：采样参数设 null 表示不向服务端发该参数，由服务端使用其默认；不应以 0 代替。

supportImage 的 null：JSON 导入得到的模型可能没带这个字段，此时按"支持图片"处理，不会报错。

默认模型没注册：agentConfig.defaultModel 指向的别名如果不在 models 里，调用时会报"ChatService 未注册"。

相关：接入向量模型、配置导出与导入、基础对话

编排任务里每个节点插件都有一组运行开关，例如超时时长、是否开启思考、使用哪套话术。这些值不写死在插件代码里，而通过配置快照的 plugins 块承载。配置快照的 plugins 块承载每个插件的一组设置；本节说明其结构及插件端的读取接口。

场景

编排任务通常包含多个节点插件，分别承担取数、AI 处理、判断等职责。每个插件各自需要一组开关，并在不同部署环境中取不同值。这些设置随整套配置一起导出与导入，插件在运行时直接读取，无需在构造阶段逐个手写。

plugins 块的结构

plugins 是一个映射：插件 id → 这个插件的一组设置。

"plugins": {
  "ai-chat-node": {
    "version": "1.0.0",
    "settings": {
      "llmTimeoutSeconds": 60,
      "enableThinking": true,
      "systemHint": "回答要简短"
    }
  },
  "data-fetch-node": {
    "version": "1.0.0",
    "settings": {
      "endpoint": "https://internal.example.com/api",
      "maxRows": 200
    }
  }
}

外层的 ai-chat-node 是插件 id；里面 PluginSettings 有两个字段：

字段	含义
version	插件版本，导入时用来判断兼容性
settings	设置键值，一个 Map<String, Object>

每个设置项的形态由插件用 PluginSettingDef 描述：key、type（string / number / boolean / secret / enum）、label、description、defaultValue、options（enum 用）、required、placeholder。其中 type=secret 的项会被当成凭据，导出时按凭据策略处理。这份定义由插件提供，界面据此渲染出表单；值则统一落在上面这个 plugins 块里。

读写设置的几个方法

都挂在配置快照 rt.declaration() 上：

方法	作用
setPluginSetting(pluginId, key, value)	写一个设置值；插件或设置容器不存在时会自动创建
setPluginSettings(pluginId, map)	批量写
pluginSettingsOf(pluginId)	取整个设置容器（PluginSettings），不存在返回 null
pluginSetting(pluginId, key)	读字符串值；未配置或键不存在返回 null
pluginSetting(pluginId, key, def)	读字符串值，空则回落 def
pluginSettingLong(pluginId, key, def)	按整数读，缺失或解析失败回落 def
pluginSettingBool(pluginId, key, def)	按布尔读，缺失回落 def

以下为取值细节：

pluginSetting 一律返回字符串形态（内部用 String.valueOf），所以数字/布尔存进去也读得出来。

pluginSettingLong：值不是合法整数时，打一条日志并返回默认值，不抛异常。

pluginSettingBool："1" 或能解析为 true 的字符串算真，其他字符串算假；缺失才回落默认。

写入 null：setPluginSetting(pluginId, key, null) 等于删除这个键，不是写空值。

最小可用代码

import net.itzq.mira.modules.runtime.KernelRuntime;
import net.itzq.mira.modules.config.GlobalConfigManager;
import net.itzq.mira.modules.config.PluginSettings;

import java.util.HashMap;
import java.util.Map;

public class PluginSettingsDemo {

    public static void main(String[] args) {
        KernelRuntime rt = KernelRuntime.builder()
                .name("plugin-demo")
                .dataDir("D:/my-app/data")
                .build();
        KernelRuntime.installDefault(rt);
        rt.start();

        GlobalConfigManager decl = rt.declaration();

        // 1) 写一组插件设置（比如界面上的"保存"按钮触发）
        Map<String, Object> settings = new HashMap<>();
        settings.put("llmTimeoutSeconds", 60);
        settings.put("enableThinking", true);
        settings.put("systemHint", "回答要简短");
        decl.setPluginSettings("ai-chat-node", settings);

        // 2) 插件执行时读出来用
        String hint = decl.pluginSetting("ai-chat-node", "systemHint", "你是一个助手");
        long timeout = decl.pluginSettingLong("ai-chat-node", "llmTimeoutSeconds", 30L);
        boolean thinking = decl.pluginSettingBool("ai-chat-node", "enableThinking", false);

        System.out.println("提示词   = " + hint);
        System.out.println("超时(秒) = " + timeout);
        System.out.println("思考模式 = " + thinking);

        // 3) 拿整个容器看看
        PluginSettings ps = decl.pluginSettingsOf("ai-chat-node");
        System.out.println("插件版本 = " + ps.getVersion());
        System.out.println("全部设置 = " + ps.getSettings());

        // 4) 读取一个没配过的键，走默认值
        System.out.println("兜底值   = " + decl.pluginSetting("ai-chat-node", "notSet", "默认"));

        rt.close();
    }
}

跑起来会看到什么

提示词   = 回答要简短
超时(秒) = 60
思考模式 = true
插件版本 = null
全部设置 = {enableThinking=true, systemHint=回答要简短, llmTimeoutSeconds=60}
兜底值   = 默认

插件版本 为 null，因为直接写设置值，没有设置 version。带上版本可手动构造一个 PluginSettings 对象：

PluginSettings ps = new PluginSettings();
ps.setVersion("1.0.0");
ps.getSettings().put("systemHint", "回答要简短");
rt.declaration().getPlugins().put("ai-chat-node", ps);

换个场景怎么改

让运维在界面上改这些值

流程是：界面读 pluginSettingsOf(pluginId) 回显 → 用户改 → 保存时调 setPluginSetting(...) 或 setPluginSettings(...) 写回配置快照。

写完之后，把"保存"接到应用的统一"应用配置"出口上即可：

// 设置面板保存后
decl.setPluginSettings("ai-chat-node", settings);
// 走统一的应用出口（复用配置中心的"应用"动作）
decl.applyAllInstance();

插件设置在插件执行时直接读配置快照，值写入后下一次执行即生效；applyAllInstance() 负责把模型与向量模型重新注册进运行时。两者一同调用无副作用，保存后统一调用一次即可。

其他常见改法

目标	改哪儿
多个插件各自一组	换 pluginId 再写一遍，互不影响
一个插件改一项	setPluginSetting(pluginId, key, value)
删掉一项	setPluginSetting(pluginId, key, null)
敏感值（密钥类）	在插件的设置定义里把该项 type 设为 secret，导出时自动按凭据策略处理

注意事项

插件 id 保持一致：plugins 按 id 归类，导出与导入均依赖它对齐。

读之前判空：pluginSettingsOf(pluginId) 在插件没配过时返回 null；pluginSetting(...) 系列则安全地返回默认值。

类型转换由调用方负责：设置值底层为 Object，pluginSettingLong / pluginSettingBool 代为转换，转换失败仅回落默认值、不报错，因此无法用于发现配置写错。

相关：节点配置：这个节点需要什么、配置中心

本篇说明如何将会话的历史消息与过程事件持久化，以实现会话列表、历史记录，以及刷新页面后仍能恢复答案。

场景

某对话应用存在如下情况：刷新页面后，之前的问答丢失；也没有可供继续的会话列表。将每轮消息落库，并把过程中产生的思考、工具调用等事件按序存储，即可支持回放。

内核将"是否存储、存储位置"交由调用方决定：只依赖一个接口 PersistencePort。由调用方实现，内核在相应时机回调；不实现时，会话仅存在于内存，运行结束即丢弃。

最小可用代码

先用内存版验证链路（尚未建库也可执行）：

import net.itzq.mira.modules.ai.client.openai.chat.entity.ChatMessage;
import net.itzq.mira.modules.ai.entity.chat.AnsResponse;
import net.itzq.mira.modules.ai.persistence.PersistencePort;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/** 用内存 Map 实现持久化：够验证链路，重启会丢。 */
public class MemoryPersistence implements PersistencePort {

    private final Map<String, List<ChatMessage>> contexts = new ConcurrentHashMap<>();
    private final Map<String, List<AnsResponse>> events = new ConcurrentHashMap<>();
    private final Set<String> sessions = ConcurrentHashMap.newKeySet();

    @Override
    public List<ChatMessage> loadContext(String historyId) {
        List<ChatMessage> saved = contexts.get(historyId);
        return saved == null ? new ArrayList<ChatMessage>() : new ArrayList<ChatMessage>(saved);
    }

    @Override
    public void persistContext(String historyId, List<ChatMessage> messages) {
        // 内核每轮只把「本轮新增」的消息交给调用方，按 historyId 追加即可
        contexts.computeIfAbsent(historyId, k -> new ArrayList<ChatMessage>()).addAll(messages);
    }

    @Override
    public void appendEvent(String historyId, AnsResponse event) {
        events.computeIfAbsent(historyId, k -> new ArrayList<AnsResponse>()).add(event);
    }

    @Override
    public void ensureSession(String historyId, String title, String mode) {
        sessions.add(historyId);
    }

    /** 回放：把一个会话的事件按顺序读出来 */
    public List<AnsResponse> replay(String historyId) {
        List<AnsResponse> list = events.get(historyId);
        return list == null ? new ArrayList<AnsResponse>() : new ArrayList<AnsResponse>(list);
    }
}

接上运行时和对话：

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.persistence.PortHistoryPersist;
import net.itzq.mira.modules.runtime.KernelRuntime;

public class PersistenceDemo {
    public static void main(String[] args) throws Exception {
        MemoryPersistence port = new MemoryPersistence();

        KernelRuntime rt = KernelRuntime.builder()
                .name("my-app")
                .dataDir("D:/my-app/data")
                .persistencePort(port)   // 也可以在 start 之后用 rt.setPersistencePort(port)
                .build()
                .start();

        String historyId = IdGen.uuid();
        // 会话列表要能看到这条，先登记一次
        port.ensureSession(historyId, "第一次对话", "chat");

        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(historyId)
                .modelAlias("deepseek-v3")
                .runtime(rt)
                .build();

        // 装载历史：这一步由应用自行调用（内核不知道存储长什么样）
        holder.getHistory().addAll(port.loadContext(historyId));

        AutoAgent agent = new AutoAgent(holder);
        // 让内核在每轮把新消息、事件交回给持久化接口
        agent.setHistoryPersist(PortHistoryPersist.of(port, historyId));

        agent.chatStream("帮我写一句项目简介").await();

        // 刷新页面时：重新装载上下文 + 回放事件
        System.out.println("历史消息数: " + port.loadContext(historyId).size());
        System.out.println("事件数: " + port.replay(historyId).size());
    }
}

这五个方法分别在什么时候被调用

loadContext(historyId)：由应用调用。开新一轮会话前，把历史消息灌进上下文（holder.getHistory()）。内核不代调，因为它不知道存储长什么样。

persistContext(historyId, messages)：内核在每轮对话结束、消息落库回调触发时调用。参数是本轮新增的消息（不是整个上下文），按 historyId 追加即可。

appendEvent(historyId, event)：内核把一条条 AnsResponse 事件交给调用方。默认经 PortHistoryPersist 转发；若事件已在管道中落库，构造时传 persistEvents=false，避免重复落库。

ensureSession(historyId, title, mode)：由应用调用。新建会话时登记一次，历史面板才会出现这条会话；mode 由实现方定义展示分组语义（例如 chat）。

isEnabled()：执行前的开关判断。默认实现返回 true；内置的 PersistencePort.NOOP 返回 false，表示"即用即释放"。

不实现会怎样：AgentContextHolder 和运行时默认都用 PersistencePort.NOOP——不落库、没记忆，每一轮跑完消息就散在内存里，进程重启即丢。

AbstractHistoryPersist / PortHistoryPersist 减少了哪些工作量

内核 agent 循环的落库回调其实是 AbstractHistoryPersist（两个抽象方法：saveChatMessages、saveEventMessages）。接入持久化无需实现它——PortHistoryPersist.of(port, historyId) 已将实现的 PersistencePort 转为该回调。接入时调用 agent.setHistoryPersist(...) 即可。

也无需自行攒批：内核会按批回调，攒批、清队列这些都在内核侧完成。

事件回放怎么用

appendEvent 存储的均为 AnsResponse，带 type（ChatContent、ChatReasonContent、CallToolBegin、CallToolEnd、ChatEnd 等）及 historyId/msgId。按顺序读取并交给前端，即可重放整条时间线；前端按 type 分流渲染。

跑起来会看到什么

第一轮对话正常出结果，同时消息和事件被写进内存 Map。

历史消息数 和 事件数 都大于 0。

若将这段逻辑接入 HTTP 接口：刷新页面时前端以 historyId 重新请求，返回 loadContext 的消息与 replay 的事件，页面即可恢复原状。

换个场景怎么改

目标存储	需要动的
MySQL / 任意关系库	只改 MemoryPersistence 里的方法体：loadContext 查表、persistContext 批量 insert、appendEvent insert 事件行、ensureSession insert 会话行；ChatMessage 序列化为 JSON 存一列即可
Redis	同样只改方法体：把三个容器换成 Redis 的 list/hash；appendEvent 用 RPUSH 天然保序
本地文件	每个 historyId 一个 JSON 文件，persistContext 追加、appendEvent 一行一行追加
换实现不用改业务代码	实现 PersistencePort 后 .persistencePort(port) 或 rt.setPersistencePort(port)；对话侧一行不用改
事件已自行落过库	PortHistoryPersist.of(port, historyId, false)，避免重复落库

注意事项

先登记会话：不调 ensureSession，loadContext/persistContext 照样能工作，但会话列表里不会出现这条。

persistContext 拿到的不是全量：是"本轮新增消息"。按 historyId 追加，不应覆盖整表。

port 为 null 会静默退化：PortHistoryPersist.of(port, ...) 传 null 时退化成 NOOP，不报错，但也不存。

顺序：先 loadContext 灌历史，再 setHistoryPersist 开跑，两边都用同一个 historyId。

锚点字段：交给持久化的 user 消息可能是 PersistedMessage（ChatMessage 的子类，多一个轮次锚点 id）。按运行时类型 JSON 序列化时该字段自然带出，读回时未知字段被忽略，不影响其作为普通消息使用。

相关：基础对话 · 流式输出 · 内核运行时装配

会话附件将用户上传的文件抽取为纯文本后存储，AI 可在本次会话内读取、搜索。

内核只提出了一种附件的简易存储方案，构建了一个小型虚拟”文件系统“充当”知识库“，不涉及把上传的文件变成文本。文本转换通常借助视觉模型、光学字符识别（OCR）、MinerU、Docling等框架辅助实现。

场景

以带附件上传的助手为例：用户在对话中提交一个 PDF、一个 Word 或一张图片，需要先将其抽取为 markdown（或任意纯文本），因为 AI 无法直接读取原始二进制字节。抽取后产生两个问题：

这些文本存于何处？全部放入系统提示词会使提示词过长，且多数情况下并不需要。

不同用户、不同会话的附件需彼此隔离。

内核负责此事的组件是 VFS：一次会话对应一个 zip 文件，zip 内为一个普通文本文件系统。AI 可列目录、按关键字搜索、按路径读取文件。

最小可用代码

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.runtime.KernelRuntime;
import net.itzq.mira.modules.vfs.VFS;
import net.itzq.mira.modules.vfs.model.SearchResult;

import java.util.Arrays;
import java.util.List;

public class VfsDemo {
    public static void main(String[] args) throws Exception {
        // 1. 起运行时：dataDir 就是 VFS 的落盘根目录
        KernelRuntime rt = KernelRuntime.builder()
                .name("my-app")
                .dataDir("D:/my-app/data")
                .build()
                .start();

        // 2. 一次会话一个 id，必须是 IdGen.uuid()（32 位、无连字符）
        String sessionId = IdGen.uuid();

        // 3. 取会话文件系统。此刻磁盘上还没有 zip，只是算好了路径
        VFS vfs = rt.vfs().loadVfs(sessionId);
        try {
            // 4. 存附件：把抽取好的纯文本写进去
            //    addDocument 返回虚拟路径（docId），后续都按这个路径读
            String md = "# 季度报告\n本季度营收同比增长 12%。";
            String docPath = vfs.addDocument(
                    "report.md",           // 文件名
                    md.getBytes("UTF-8"),  // 源字节；传 null 时用 textChunks 拼出来的文本代替
                    "/docs",               // 目录
                    Arrays.asList(md));    // 分段文本，这里只有一段
            System.out.println("已存入: " + docPath);

            // 也可以直接按路径写一段文本
            vfs.write("/docs/note.md", "这是会议备注。");

            // 5. 读回来
            System.out.println("内容: " + vfs.readString("/docs/report.md"));

            // 6. 看目录树
            System.out.println("目录树:\n" + vfs.listTree());

            // 7. 按正则搜关键字，返回命中的文件列表
            List<SearchResult> hits = vfs.grep("营收", 10);
            for (SearchResult r : hits) {
                System.out.println("命中: " + r.getFilePath() + " 来源=" + r.getSource());
            }
        } finally {
            // 8. 释放底层 zip 句柄
            vfs.close();
        }

        // 9. 让 AI 用起来：把同一个 id 写进会话上下文，挂 VFS 工具
        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(sessionId)      // 历史 id
                .vfsId(sessionId)          // 文件 id：一个会话对应一个
                .modelAlias("deepseek-v3")
                .runtime(rt)
                .build();

        AutoAgent agent = new AutoAgent(holder);
        agent.mountToolsIfAbsent(AutoAgent.getDefaultVfsReadTools());
        agent.chatStream("帮我看看 /docs/report.md 里营收涨了多少").await();
    }
}

说明几件事

zip 的落盘路径规则是 <dataDir>/ab/cd/<sessionId>.zip：取 sessionId 的前 2 位做第一级目录、第 3~4 位做第二级目录，避免所有 zip 堆在一个目录里。上面的例子会落到 D:/my-app/data/<前2位>/<第3~4位>/<sessionId>.zip。

vfsId 与 historyId 使用同一个 sessionId 是常见做法。两者也可分开——内核不强制相等，调用方保证"一个会话对应一个 id"时，工具即可定位同一份文件。

AI 侧通过 holder.getVfsId() 获取 id。挂载 vfs_file_read、vfs_list_files、vfs_grep（需要写入时再挂载 vfs_file_write、vfs_file_edit、vfs_glob、vfs_explorer）后，AI 即可用这些工具读取附件。id 为空时，工具直接返回"虚拟文件系统未初始化"。

跑起来会看到什么

控制台依次打印 已存入: /docs/report.md、文件内容、目录树，以及 命中: /docs/report.md 来源=grep。

目录树里能看到 /、/docs/、/docs/report.md、/docs/note.md。

磁盘上出现一个 zip：<dataDir>/ab/cd/<sessionId>.zip。

时间点：loadVfs 步骤不产生任何文件；直到首次 addDocument 或 write，zip 才真正创建。

最后那轮对话里，可看到 AI 调用 vfs_file_read 之类的工具，把文件内容读进上下文再回答。

换个场景怎么改

目标	改哪里
一个用户有多个会话	每个会话各自 IdGen.uuid() 当 sessionId；用数据表存储"用户 ↔ 会话 ↔ sessionId"的对应关系
附件只读，不许 AI 改	工具白名单中不挂 vfs_file_write、vfs_file_edit；仅保留 AutoAgent.getDefaultVfsReadTools() 返回的工具
附件也要能被 AI 编辑	白名单再加上 vfs_file_write、vfs_file_edit
换个落盘位置	改运行时的 dataDir（或用 WorkspaceConfig 单独给 VFS 指定数据目录）
若需让 AI 直接操作真实项目目录	属于另一类工作空间，见「工作空间」篇

注意事项

sessionId 格式：必须是 32 位无连字符的十六进制字符串，用 IdGen.uuid() 生成；传别的（比如带连字符的 UUID）会直接抛异常。

懒加载：读不存在的文件会抛 NoSuchFileException，不会自动创建空文件。不确定是否存在时，可先用 vfs.exists(path) 判断；listTree() 在没有 zip 时返回空字符串。

覆盖写：addDocument 和 write 都是覆盖语义，同一个虚拟路径再写一次会替换掉旧内容。

用完需关闭：VFS 实现了 Closeable，使用后应调用 close()，或用 try-with-resources 管理。

路径用正斜杠：虚拟路径统一以 / 开头（如 /docs/report.md），内部会把反斜杠和多余的斜杠归一化。

相关：内置工具一览 · 工作空间（Workspace） · 内核运行时装配

工作空间将 AI 的读文件、改文件、跑命令约束在指定的一个真实项目目录内。

场景

编程助手是一个典型场景：指定一个代码目录（如 D:/projects/demo），AI 在该目录内读文件、改文件、搜代码、跑构建命令。文件操作被约束在该目录内，不访问目录外的磁盘内容，代码内容也不必每次都放入提示词。

内核通过给会话上下文设置 workspacePath 约束文件操作范围，代码类工具（Bash、Read、Write、Edit、Glob、Grep 等）均基于该路径工作。

最小可用代码

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.runtime.KernelRuntime;

public class WorkspaceDemo {
    public static void main(String[] args) throws Exception {
        KernelRuntime rt = KernelRuntime.builder()
                .name("code-assistant")
                .dataDir("D:/code-assistant/data")
                .build()
                .start();

        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(IdGen.uuid())
                .modelAlias("deepseek-v3")
                .prompt("你是一个严谨的编程助手，改动前后都要说明原因。")
                // 关键：AI 能碰的真实项目目录
                .workspacePath("D:/projects/demo")
                .runtime(rt)
                .build();

        AutoAgent agent = new AutoAgent(holder);
        // 全量工具：Bash / Edit / Read / Write / Glob / Grep / list_files / code_explorer
        agent.mountFullCodeTools();

        // 跑一轮"改文件"的对话
        agent.chatStream("把 README.md 里的项目名改成 demo-service").await();
    }
}

内核里还有一层"文件存储"抽象

上面的 workspacePath 是 AI 直接操作的真实目录。内核另外提供 Workspace 抽象，用于把文件存入内核管理的存储位置。两者都称为工作空间，但落点不同：

FileWorkspace：把虚拟路径落到真实磁盘，目录是 <dataDir>/ab/cd/<sessionId>/storage。

VFS：把内容落到一个 zip 文件（附件场景常用，见「会话附件」篇）。

LocalFileSpace：直接以指定的任意真实目录为根，接口里用 / 分隔的虚拟路径，内部映射到真实文件。

WorkspaceConfig 控制落盘和展示：

import net.itzq.mira.modules.runtime.KernelRuntime;
import net.itzq.mira.modules.workspace.WorkspaceConfig;

WorkspaceConfig wc = new WorkspaceConfig();
wc.setDataDir("D:/my-app/data"); // 文件落盘的根目录
wc.setMapDir("/workspace");      // 映射根目录（展示用）；不设时映射路径 == 真实路径

KernelRuntime rt = KernelRuntime.builder()
        .name("my-app")
        .dataDir("D:/my-app/data")
        .vfsConfig(wc)
        .build()
        .start();

mapDir 只影响"映射路径"这个概念：虚拟路径 /data/a.txt 的真实路径是 <存储根>/data/a.txt，映射路径是 /workspace/data/a.txt。mapDir 留空时，映射路径就等于真实路径。

以真实目录为根直接读写：

import net.itzq.mira.modules.workspace.LocalFileSpace;
import net.itzq.mira.modules.workspace.Workspace;

Workspace wk = LocalFileSpace.open("D:/projects/demo"); // 目录必须已存在，不会自动创建
wk.write("/notes/todo.md", "待办：补测试");
System.out.println(wk.readString("/notes/todo.md"));
System.out.println(wk.listTree());
wk.close();

跑起来会看到什么

AI 那轮对话里会连续出现工具调用：先用 Read 读 README.md，再用 Edit（或 Write）改内容，改完可能用 Grep/Glob 复查。

指定目录下的文件被修改：D:/projects/demo/README.md。

AI 执行 Bash 时，输出中包含"工作目录 / 命令 / 退出码"以及命令输出；工作目录默认即 workspacePath。

LocalFileSpace 那段会打印 待办：补测试 和一份目录树。

换个场景怎么改

只读模式：把 agent.mountFullCodeTools() 换成 agent.mountReadOnlyTools()，或白名单直接用 AutoAgent.readOnlyTools()——它不含 Bash、Edit、Write，AI 只能看不能改。

限制 AI 仅访问子目录：将 workspacePath 指向子目录即可，例如 D:/projects/demo/src。

多用户各自一个目录：每个用户的运行时给不同 dataDir，workspacePath 各自指定；同一个运行时下也可以按会话给不同目录。

避免写入真实磁盘：改用 VFS，内容落 zip，见「会话附件」篇。

换一个"存储根"：改 WorkspaceConfig.dataDir；仅需调整展示路径时改 mapDir。

注意事项

Bash 需要 workspacePath：workspacePath 为空时，Bash 工具会直接拒绝执行并返回"当前未设置工作空间路径，禁用 Bash 工具"。

workdir 必须是已存在的目录：Bash 的 workdir 参数给的是相对工作空间的路径或绝对路径，指向不存在的目录会报错；每条命令开启新的 shell，无法通过 cd 维持命令间的状态。

降权执行（可选）：配置快照里的 AgentConfig.bashSandBoxUser 可以让 Bash 命令以指定用户身份执行；不设置时默认取环境变量 SANDBOX_USER，取不到就不降权。

危险命令只告警：内核会识别 rm -rf、git push --force、DROP TABLE 这类模式并写日志，但默认不阻断；需在调用前拦截时，可用工具调用前钩子（EventHook）实现。

阻塞命令会被拒：sleep 这类阻塞命令会被直接拦下。

越界防护：存储层对虚拟路径做 ../ 逃逸检查，路径尝试超出存储根时抛出"非法路径（越界）"。

相关：内置工具一览 · 会话附件（VFS） · 接入一个模型

已有的 REST 接口通过一份"接口说明"即可变为 AI 可调用工具，无需为每个接口编写工具类。

场景

已有运行稳定的接口（查订单、查库存、改地址）。希望由 AI 查询订单状态时，为每个接口编写 Java 工具类较为繁琐，且接口增多时需同步修改代码。

所需仅为填写若干字段——工具名、请求地址、参数——AI 即可调用。内核中的 HTTP 工具 即用于此。

最小可用代码

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.http.HttpParam;
import net.itzq.mira.modules.ai.http.HttpToolDefine;
import net.itzq.mira.modules.ai.http.HttpToolMeta;
import net.itzq.mira.modules.ai.http.HttpToolRegistry;
import net.itzq.mira.modules.runtime.KernelRuntime;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;

public class HttpToolDemo {
    public static void main(String[] args) throws Exception {
        KernelRuntime rt = KernelRuntime.builder()
                .name("my-app")
                .dataDir("D:/my-app/data")
                .build()
                .start();

        // 1. 描述一个接口：路径里用 {id} 当占位符
        HttpParam id = new HttpParam();
        id.setName("id");
        id.setIn(HttpParam.In.PATH);      // 这个参数要填到路径里
        id.setRequired(true);
        id.setType("string");             // 给模型看的类型
        id.setDescription("订单号");

        HttpToolMeta meta = new HttpToolMeta();
        meta.setName("order_get_by_id");  // 工具函数名，唯一
        meta.setSummary("按订单号查订单");
        meta.setDescription("调用订单服务，返回订单详情 JSON");
        meta.setHttpMethod("GET");
        meta.setServerUrl("https://api.mycompany.com");
        meta.setPathTemplate("/orders/{id}");
        meta.setParams(Arrays.asList(id));
        meta.setTimeoutMs(5000);          // 不写就用全局默认 10 秒
        meta.setMaxResponseBytes(65536);  // 响应太长就截断，不写就用全局默认 64KB

        // 2. 注册两处：一处让执行时能按名字回查这份说明，一处让模型"看得见"这个工具
        HttpToolRegistry.register(meta);
        rt.toolRegistry().registerTool(new HttpToolDefine(meta));

        // 3. 会话白名单里加上这个工具名
        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(IdGen.uuid())
                .modelAlias("deepseek-v3")
                .runtime(rt)
                .build();

        Set<String> whitelist = new LinkedHashSet<>(AutoAgent.systemBaselineTools(null));
        whitelist.add(meta.getName());

        AutoAgent agent = new AutoAgent(holder);
        agent.mountToolsIfAbsent(whitelist.toArray(new String[0]));

        // 4. 开聊
        agent.chatStream("帮我查一下订单 A10086 现在什么状态").await();
    }
}

参数位置

HttpParam.setIn(...) 决定参数在 HTTP 请求中的位置：

位置	含义
HttpParam.In.PATH	填进 pathTemplate 里的 {名字} 占位符，值会做 URL 编码
HttpParam.In.QUERY	拼成 URL 查询串；值是数组时会展开成多个同名参数
HttpParam.In.HEADER	放进请求头
HttpParam.In.BODY	放进 JSON 请求体
HttpParam.In.FORM	放进表单（application/x-www-form-urlencoded）
HttpParam.In.COOKIE	放进 Cookie

跑起来会看到什么

对话里 AI 会调用 order_get_by_id，参数是 {"id":"A10086"}；前端工具时间线上能看到这次调用。

工具返回一段 JSON 文本，形如 {"status":200,"body":{...订单详情...}}：status 为 HTTP 状态码，body 为自动解析后的响应体（解析失败时保留原文）。

响应超过 maxResponseBytes 时，末尾追加 ...(truncated)，表示内容被截断。

连接失败、超时或抛出异常时，返回 {"error":"..."}，不会中断整个对话。

换个场景怎么改

目标	改哪里
改成 POST 提交 JSON	meta.setHttpMethod("POST")；参数用 In.BODY。只有一个 BODY 参数时，模型给的实参直接当请求体；多个 BODY 参数时自动拼成 JSON 对象，并加 Content-Type: application/json
提交表单	参数用 In.FORM，请求头会自动设成 application/x-www-form-urlencoded
加查询条件	参数用 In.QUERY
固定鉴权头	meta.setHeaders(map) 写死；或让模型传的话用 In.HEADER；或全局统一加用 HttpToolInvoker.setGlobalHeaderProvider(() -> headers)（每次请求现取）
统一调超时和截断上限	HttpToolInvoker.setDefaultTimeoutMs(毫秒)、HttpToolInvoker.setDefaultMaxBytes(字节)；单个接口想单独设，就在 meta 上写
下线一个接口	HttpToolRegistry.unregister("order_get_by_id") 加上 rt.toolRegistry().unregisterTool("order_get_by_id")
一批同前缀接口一起下线	HttpToolRegistry.unregisterByPrefix("order_") 加上 rt.toolRegistry().unregisterByPrefix("order_")
不同会话给不同接口	白名单按会话拼，只把该会话允许的 meta.getName() 加进去

使用要点

需写入两个注册表，这是最易遗漏的一步：
HttpToolRegistry.register(meta) 负责执行时按工具名回查这份接口说明；

rt.toolRegistry().registerTool(new HttpToolDefine(meta)) 负责让工具出现在模型的工具列表里。

只注册第一个，模型根本不知道有这个工具；只注册第二个，模型能调但执行时查不到说明，会返回 {"error":"工具元数据缺失"}。

为内存表：接口说明仅存于进程内存，重启后需重新注册。常驻应用宜在启动装配阶段统一注册。

type 仅作模型可见的类型说明：填写 integer 只影响生成的参数描述，不会自动将模型传入的字符串转为数字；类型对齐需在接口侧保证。

必填仅通过说明，不通过拦截：setRequired(true) 写入给模型的参数说明，AI 通常据此传参，但内核不代为拦截；缺少参数时路径占位符留空。

返回值始终为字符串：status/body 或 error；如需结构化数据，需自行解析这段 JSON。

接口名需唯一：函数名全局唯一，且不得与内置工具名重名，宜统一加业务前缀（如 order_）。

相关：自定义工具 · 内置工具一览 · 配置中心

已有的 MCP 服务接入内核后，AI 可调用其提供的工具，无需自行编写工具代码。

场景

示例：代码助手需要读写本地文件。这类能力已有现成的 MCP 服务实现，通过一段配置即可接入，无需重写。

内核通过 MCP 支持 实现：提供一段描述服务的 JSON，内核连接一次并列出服务提供的工具；之后 AI 需要调用时，通过统一的 mcp_call 工具发起。

最小可用代码

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.core.utils.PropsMap;
import net.itzq.mira.core.utils.PromptLoader;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.mcp.McpManager;
import net.itzq.mira.modules.ai.mcp.McpPrepared;
import net.itzq.mira.modules.ai.mcp.McpToolInfo;
import net.itzq.mira.modules.runtime.KernelRuntime;

import java.util.LinkedHashSet;
import java.util.Set;

public class McpDemo {
    public static void main(String[] args) throws Exception {
        KernelRuntime rt = KernelRuntime.builder()
                .name("my-app")
                .dataDir("D:/my-app/data")
                .build()
                .start();

        // 1. 一段 MCP 服务配置（JSON 字符串）。这里用命令行方式（stdio）拉起一个本地服务
        String mcpJson = "{\"mcpServers\":{"
                + "\"filesystem\":{"
                + "\"command\":\"npx\","
                + "\"args\":[\"-y\",\"@modelcontextprotocol/server-filesystem\",\"D:/projects/demo\"]"
                + "}}}";

        // 2. 探活：连上去 -> 列出它提供的工具 -> 断开。得到"这次能用哪些工具"
        McpPrepared prepared = McpManager.prepare(mcpJson);
        for (McpToolInfo t : prepared.getTools()) {
            System.out.println("可用: " + t.getFullName() + " -> " + t.getDescription());
        }

        // 3. 会话上下文里带上这份配置
        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(IdGen.uuid())
                .modelAlias("deepseek-v3")
                .runtime(rt)
                .build();
        holder.setMcpConfig(prepared);

        // 4. 白名单 = 系统基线工具 + mcp_call（有 MCP 工具时才会加进去）
        Set<String> whitelist = new LinkedHashSet<>(AutoAgent.systemBaselineTools(null));
        AutoAgent.mountSkillAndMcpTools(whitelist, null, prepared);

        AutoAgent agent = new AutoAgent(holder);
        agent.mountToolsIfAbsent(whitelist.toArray(new String[0]));

        // 5. 把 MCP 工具清单写进系统提示词，AI 才知道有哪些工具可以调
        PropsMap params = AutoAgent.buildSkillMcpPromptParams(null, prepared);
        holder.setPrompt(PromptLoader.processTemplate(
                PromptLoader.createTemplate("你是一个助手。\n\n可用 MCP 工具:\n${mcpTools}"),
                params));

        // 6. 开聊：AI 会调 mcp_call，内核按需现连服务再执行
        agent.chatStream("看看 D:/projects/demo 下都有什么文件").await();
    }
}

补充说明

每个 MCP 工具都有一个全名，形如 mcp__服务名__工具名，例如 mcp__filesystem__read_file。这个名字在探活时就能拿到。

换个连法只有一段 JSON 的差别。HTTP 方式（SSE）长这样：
{"mcpServers":{"weather":{"url":"http://localhost:3001/sse"}}}

一次挂多个服务，就是在 mcpServers 里写多个键，各自一套 command/args 或 url。命令行方式还可以加 "env":{"KEY":"值"} 给子进程传环境变量。

跑起来会看到什么

McpManager.prepare(...) 会实际启动或连接服务，并在控制台打印其提供的工具全名与描述。

对话时，AI 先调 mcp_call，参数是 tool_name（工具全名）和 arguments（一个 JSON 字符串形式的参数对象）；内核按放入会话上下文的那份配置现连服务、把参数递过去执行、拿到结果再断开，最终把结果以 JSON 文本返回给模型。

服务无法启动时，探活这一步会列不出工具（列表为空），后续 AI 也不会去调。

换个场景怎么改

目标	改哪里
从命令行方式换成 HTTP 方式	把服务配置里的 command/args 换成 url
一次挂多个服务	在 mcpServers 里加多个服务名，每个写自己的 command/args 或 url
给服务传密钥或环境变量	命令行方式在服务配置里加 "env":{"KEY":"值"}；密钥不写死在代码里
不同用户/会话挂不同的服务	每次会话各自 McpManager.prepare(...) 一份，写进自己的 holder.setMcpConfig(...)
只让 AI 用其中几个工具	内核层做不到：白名单里只有统一的 mcp_call，要收窄只能在服务端裁剪，或拆成不同服务挂

使用要点

配置需落到会话上下文：mcp_call 从 holder.getMcpConfig() 读取配置；未调用 setMcpConfig 时，AI 调工具会收到"本次对话未配置MCP"。

一次调用一次连接：内核不常驻服务连接，每次 mcp_call 都按配置现连。本地命令行服务存在进程启动开销，网络服务需关注超时，避免在高峰期频繁调用。

探活即实际连接：prepare 非纯本地解析，会实际连接服务并列出工具，因此可能失败或较慢，宜放在会话准备阶段，而非对话主流程。

JSON 为字符串：配置需注意转义；密钥从环境变量或配置快照读取，不写入代码。

工具名分隔符：全名以双下划线分段，拼接时需保持一致。

相关：技能包（Skills） · 工具调用 · 配置中心

图片作为对话消息的一部分发送给模型，模型在回答中描述图片内容。

场景

示例：用户贴一张报错截图并询问错误原因；图片随问题一同发送给模型，模型在回答中描述图片内容。

图片理解不是独立能力，而是对话的一部分：图片作为消息发出，其余流程与普通对话一致。

最小可用代码

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.runtime.KernelRuntime;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.client.openai.chat.entity.ChatMessage;

import java.util.Arrays;
import java.util.List;

public class ImageChatDemo {

    // 看图要选支持视觉的对话模型（配置里 supportImage 为 1）
    private static final String DECLARATION_JSON =
            "{\"schemaVersion\":\"1.0.0\","
            + "\"models\":[{\"alias\":\"gpt-4o\",\"providerName\":\"openai\","
            + "\"apiModelName\":\"gpt-4o\",\"apiHost\":\"https://api.openai.com\","
            + "\"apiEndpoint\":\"/v1/chat/completions\",\"supportImage\":1,"
            + "\"apiKey\":\"sk-替换为实际密钥\"}],"
            + "\"agentConfig\":{\"defaultModel\":\"gpt-4o\"}}";

    public static void main(String[] args) throws Exception {
        KernelRuntime rt = KernelRuntime.builder()
                .name("my-app")
                .dataDir("D:/my-app/data")
                .declarationJson(DECLARATION_JSON)
                .build();
        KernelRuntime.installDefault(rt);
        rt.start();

        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(IdGen.uuid())
                .modelAlias("gpt-4o")           // 必须是支持视觉的对话模型
                .prompt("你是一个严谨、简洁的中文助手。")
                .runtime(rt)
                .build();

        AutoAgent agent = new AutoAgent(holder);

        // 图片既可以是公网 URL，也可以是 data:image/png;base64,xxxx 这种内联数据
        List<String> images = Arrays.asList(
                "https://example.com/error.png",
                "data:image/png;base64,iVBORw0KGgo...");
        agent.chatStream("这张截图里报的什么错？", images).await();

        // 也可以把图片消息直接塞进历史
        holder.addHistory(ChatMessage.withUser("再看看这张", "https://example.com/error2.png"));
        agent.chatStream("这两张图说的是一回事吗？").await();

        rt.close();
    }
}

跑起来会看到什么

两轮都不调任何工具，模型直接在回答里描述图片内容。

第一轮回答会说清截图上的报错信息。

第二轮因为历史里带着第二张图，模型能同时看到两张图并做对比。

本页未注册监听器，控制台没有逐字输出；分段输出的处理方式见流式输出。

换个场景怎么改

目标	改哪里
换服务商 / 换网关	改配置快照里这个模型的 apiHost + apiEndpoint + apiKey；网关要是要求特殊请求头，用 apiHeaders 接管
换成别的视觉模型	改 modelAlias("...")，同时把配置快照 models 里的 alias 对上
用户上传的图片，而不是公网 URL	本地文件读成 base64，拼成 data:image/png;base64,... 再传，和公网 URL 等价
一次发多张图	images 里多放几个元素，顺序不影响
只做纯文本对话	不传 images，用 agent.chat(...) 或 agent.chatStream(...)，见基础对话
每个用户一条独立会话	各自生成 historyId 和 userId，各建一个 holder

使用要点

取决于模型能力：发给不支持视觉的模型时，请求会失败或被忽略。配置快照中该模型的 supportImage 设为 1（不填默认按支持处理）。

流式入口需 await()：chatStream 返回倒计数锁；未调用 await() 时 main 会提前退出，回答丢失。

密钥不写入代码：从环境变量或配置快照读取值，不写死在代码中。

相关：基础对话 · 流式输出 · 接入一个模型

一份"操作手册"可打包为技能，AI 在需要时自行读取，避免将手册全文放入系统提示词。

场景

示例：客服助手处理退款、改地址、开发票等业务，每个业务对应一份内部手册，合计数万字。全部放入系统提示词会带来长度、成本与混淆问题。

需求是：系统提示词中只声明存在哪些手册，由 AI 自行决定并读取所需手册。

内核中负责该能力的是 技能。一个技能即 一个 zip 包，内含 SKILL.md（开头为元信息，其后为正文）及所需参考资料。AI 先看到技能摘要，决定使用时调用 use_skill 读取正文。

最小可用代码

技能包以目录下的 *.zip 形式存在，每个 zip 对应一个技能，文件名即其名字（slug）：

文件名：order-manual.zip

包里：SKILL.md（可以直接放在 zip 根目录，也可以放在唯一的一层顶层目录里，两种打包方式都认）

SKILL.md 开头是两个 --- 包着的元信息，字段有：name（就是 slug，要和 zip 文件名一致）、description（多行描述用 description: >）、description_zh、description_en、version、license、category、triggers（触发词列表，每行 - 词）。两个 --- 之后就是正文，也就是 AI 真正要读的内容。

将技能挂接到一次会话的完整代码如下：

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.core.utils.PropsMap;
import net.itzq.mira.core.utils.PromptLoader;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.mcp.McpPrepared;
import net.itzq.mira.modules.ai.skills.SkillEntity;
import net.itzq.mira.modules.runtime.KernelRuntime;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public class SkillsDemo {
    public static void main(String[] args) throws Exception {
        KernelRuntime rt = KernelRuntime.builder()
                .name("my-app")
                .dataDir("D:/my-app/data")
                .build()
                .start();

        // 1. 装载技能：扫描这个目录下的 *.zip（幂等，装过一次再调会跳过）
        rt.skills().init("D:/my-app/skills");

        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(IdGen.uuid())
                .modelAlias("deepseek-v3")
                .runtime(rt)
                .build();

        // 2. 本次会话要用哪几本手册，按 slug 点名
        holder.setActiveSkillSlugs(Arrays.asList("order-manual"));

        // 3. 白名单 = 系统基线工具 + 技能配套工具（use_skill / read_skill_file / expand_skill）
        Set<String> whitelist = new LinkedHashSet<>(AutoAgent.systemBaselineTools(null));
        List<SkillEntity> activeSkills = AutoAgent.resolveActiveSkills(holder);
        McpPrepared noMcp = McpPrepared.empty();
        AutoAgent.mountSkillAndMcpTools(whitelist, activeSkills, noMcp);

        AutoAgent agent = new AutoAgent(holder);
        agent.mountToolsIfAbsent(whitelist.toArray(new String[0]));

        // 4. 把技能摘要渲染进系统提示词，AI 才知道"有这么几本手册可翻"
        PropsMap params = AutoAgent.buildSkillMcpPromptParams(activeSkills, noMcp);
        String prompt = PromptLoader.processTemplate(
                PromptLoader.createTemplate(
                        "你是一个严谨的助手。\n\n可用技能:\n${skills}\n\n可用 MCP 工具:\n${mcpTools}"),
                params);
        holder.setPrompt(prompt);

        // 5. 开聊
        agent.chatStream("帮我按手册处理一笔订单退款").await();
    }
}

跑起来会看到什么

启动时会打印技能装载情况，比如 已加载技能: order-manual (订单退款手册)、SkillRepository 初始化完成，共注册 1 个技能。

系统提示词里 ${skills} 被替换成了技能的摘要行（slug + 描述），${mcpTools} 因为是空配置，被替换成空字符串。

对话时，AI 先调用 use_skill（参数 skill_name），随后获取 <skill_content>...</skill_content> 包裹的正文，并据此回答。

手册里如果还提到别的文件，AI 可以调 read_skill_file（参数 skill_name + file_path）读包里的单个文件；如果那个技能自带脚本、需要落到磁盘才能用，AI 会调 expand_skill，包会被解压到 <dataDir>/skills-expand/<skill_name>/，返回真实目录路径。

use_skill 有校验：skill_name 必须在本次会话的 activeSkillSlugs 里，否则会被拒绝。

换个场景怎么改

目标	改哪里
由 AI 按用户输入自动挑选手册	调用 rt.skills().matchSkills(用户输入) 获取触发词命中的技能列表，将 slug 传入 holder.setActiveSkillSlugs(...)
一次给多本手册	setActiveSkillSlugs(Arrays.asList("order-manual", "invoice-manual"))，多本会一起进摘要
手册里附带模板、脚本等资料	打包进 zip 的其它文件，AI 用 read_skill_file 读、用 expand_skill 解压
换技能存放目录	换成实际路径调 rt.skills().init("...")；若想让 resolveActiveSkills 自动加载，把配置快照里的技能目录（AgentConfig.skillsDir，默认 data-skills/skills）改成目录
一个进程里跑多套互不干扰的运行时	每套运行时各自 rt.skills().init(自己目录)，同名技能在两个目录里也不会串
改了技能包想重新加载	先 rt.skills().shutdown() 释放句柄，再 init(...)；只改 zip 内容不重载是不生效的

使用要点

只认 zip：技能目录里扫描的是 *.zip，散着的文件夹不会被识别。

slug 需一致：SKILL.md 中的 name 与 zip 文件名须一致，工具按该 slug 查找包。

init 幂等：已装载过的技能再次调用会被跳过。更换目录或重载需先调用 shutdown()。

未激活不可用：仅进入 activeSkillSlugs 的技能可被 AI 通过 use_skill 调用；配套的 use_skill / read_skill_file / expand_skill 三个工具，仅在本次会话存在激活技能时自动加入白名单。

会话结束应释放：rt.skills().shutdown() 清空注册表并关闭已打开的 zip 句柄。

相关：接入 MCP 工具服务 · 内置工具一览 · 配置中心

本文描述应用启动时装配内核的方式，以及装配后的使用与释放。

场景

服务常驻进程。进程启动时装配内核（配置模型、工具、挂接存储实现），之后每个请求复用同一运行时，进程退出时统一释放。

最小可用代码

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.client.config.ModelApiConfig;
import net.itzq.mira.modules.runtime.KernelRuntime;

import java.util.Arrays;

public class ServerBootstrap {

    private KernelRuntime rt;

    /** 启动时装配一次 */
    public void onStartup() {
        // ① 启动：扫描内置工具 + 应用当前配置快照
        rt = KernelRuntime.builder()
                .name("my-app")
                .dataDir("D:/my-app/data")
                .build()
                .start();

        // ② 安装为默认运行时（必须在第一次读配置之前）
        KernelRuntime.installDefault(rt);

        // ③ 写配置
        rt.declaration().setModels(Arrays.asList(ModelApiConfig.builder()
                .alias("deepseek-v3")
                .providerName("deepseek")
                .apiModelName("deepseek-chat")
                .apiHost("https://api.deepseek.com")
                .apiEndpoint("/chat/completions")
                .apiKey(System.getenv("DEEPSEEK_API_KEY"))
                .build()));
        rt.declaration().getAgentConfig().setDefaultModel("deepseek-v3");
        rt.declaration().applyAllInstance();

        // ④ 挂上持久化实现（不挂 = 跑完即弃）
        rt.setPersistencePort(new MyPersistencePort());
    }

    /** 每个请求复用同一个运行时 */
    public String onRequest(String question) {
        String historyId = IdGen.uuid();
        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(historyId)
                .modelAlias("deepseek-v3")
                .prompt("你是一个严谨的助手")
                .vfsId(historyId)
                .build();
        AutoAgent agent = new AutoAgent(holder, "demo-agent");
        return agent.chat(question);
    }

    /** 进程退出时释放 */
    public void onShutdown() {
        if (rt != null) {
            rt.close();
        }
    }

    // 占位：替换为实际实现（可参考 /guide/data/persistence）
    static class MyPersistencePort implements
            net.itzq.mira.modules.ai.persistence.PersistencePort {
        public java.util.List<net.itzq.mira.modules.ai.client.openai.chat.entity.ChatMessage>
                loadContext(String historyId) {
            return new java.util.ArrayList<>();
        }
        public void persistContext(
                String historyId,
                java.util.List<net.itzq.mira.modules.ai.client.openai.chat.entity.ChatMessage> messages) {
        }
        public void appendEvent(String historyId,
                net.itzq.mira.modules.ai.entity.chat.AnsResponse event) {
        }
        public void ensureSession(String historyId, String title, String mode) {
        }
    }
}

builder 每个参数的含义

参数	必填	含义
name(...)	否	运行时名字，只用于日志识别；不给默认叫 runtime
dataDir(...)	基本必填	数据根目录，会话附件包等文件落在这里
declarationJson(json)	否	启动时直接带一份配置快照（JSON 字符串）
persistencePort(port)	否	挂持久化实现；不挂 = 跑完即弃
vfsConfig(workspaceConfig)	否	显式指定文件读写的数据目录；不指定则跟随配置快照，配置快照没给就回落 dataDir

build() 只是构造，还没启动；build().start() 或 builder().start() 会构造并启动。

start() 做了什么

扫描内置工具：把内核自带的工具（文件读写、命令、检索、附件包、技能、MCP 等）注册进本运行时的工具注册表。

应用配置快照：把模型、embedding 装进本运行时的注册表，并设好默认模型。

start() 是幂等的：已启动过的实例再次调用无副作用，也不会重新应用配置。配置写入后通过显式调用 applyAllInstance() 生效。

close() 释放了什么

close() 会清空工具注册表、清空模型与 embedding 注册表、关闭技能仓储（释放技能包文件句柄），并将状态标记为已关闭。适用于进程退出，或一次性临时运行时使用完毕后的释放。

访问器一览

访问器	能拿到什么
declaration()	配置快照：模型、embedding、提示词、工具来源、默认值、插件设置
modelRegistry()	对话模型注册表：按别名查找模型
embeddingRegistry()	embedding 注册表
toolRegistry()	工具注册表：查工具、看数量、注册自定义工具
vfs()	会话附件包服务：按会话 id 加载附件包
skills()	技能仓储：按 slug 取技能、匹配技能
persistencePort()	当前挂的持久化实现（没挂就是空实现）

另有 exportDeclaration(policy) / importDeclaration(json) 用于配置快照的导出与导入，见配置导出与导入。

跑起来会看到什么

启动时控制台打印：

【KernelRuntime】已启动: name=my-app, tools=17, models=1
【KernelRuntime】默认运行时已安装: name=my-app, dataDir=D:/my-app/data

退出时打印：

【KernelRuntime】已关闭: name=my-app

若挂接了持久化实现，一次对话结束后，历史消息和事件即写入存储。

换个场景怎么改

目标	改哪里
启动时就带一份现成配置	用 builder().declarationJson(json)
配置由外部文件决定	用 rt.importDeclaration(json) 并检查返回的校验报告
不用默认运行时，全部显式指定	不调 installDefault；每个 context 加 .runtime(rt)
文件读写要落到别处	用 builder().vfsConfig(workspaceConfig) 指定 dataDir
不要记忆	不挂持久化，或 rt.setPersistencePort(null)
运行时用完只想清空	rt.close()

失败模式

installDefault 须在第一次读取配置之前调用：静态便捷入口会懒创建一套没有数据目录的默认运行时，若晚于首次读配置则被固定为无数据目录的实例。

写完配置须调用 applyAllInstance()：仅调用 start() 不会重新应用配置。

close() 之后发起对话无效：注册表已清空，isClosed() 为 true。

常驻服务只装配一次运行时：每个请求都新建会导致文件句柄与注册表反复重建。

相关：一个进程里跑多套运行时、配置中心、消息持久化

本篇介绍如何从零跑通第一次对话，只要一个 main 方法。

场景

先不考虑界面，就在本地写一个 Java 程序，发一句话给大模型，把回答打印出来。跑通了，再往上加工具和流式输出。

最小可用代码

第一步：引入依赖

<!-- 添加仓库 -->
<repositories>
    <repository>
        <id>itzq-repo</id>
        <url>https://maven.cnb.cool/itzq/repo/-/packages/</url>
    </repository>
</repositories>

<dependency>
    <groupId>net.itzq.mira</groupId>
    <artifactId>agent-core</artifactId>
    <version>0.2.1-SNAPSHOT</version>
</dependency>

已于多个场景验证，整体运行基本稳定，但目前仍处于持续迭代中，暂未正式发布。

第二步：一个 main 方法

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.client.config.ModelApiConfig;
import net.itzq.mira.modules.runtime.KernelRuntime;

import java.util.Arrays;

public class FirstChat {

    public static void main(String[] args) {
        // 1. 创建运行时
        KernelRuntime rt = KernelRuntime.builder()
                .name("my-first-app")
                .dataDir("D:/my-app/data")       // 会话文件都落在这里
                .build()
                .start();                        // 扫描内置工具

        // 2. 安装为默认运行时（必须在第一次读配置之前）
        KernelRuntime.installDefault(rt);

        // 3. 声明一个模型
        rt.declaration().setModels(Arrays.asList(ModelApiConfig.builder()
                .alias("deepseek-v3")            // 别名：对话时用它
                .providerName("deepseek")
                .apiModelName("deepseek-chat")   // 厂商那边的真实模型名
                .apiHost("https://api.deepseek.com")
                .apiEndpoint("/chat/completions")
                .apiKey(System.getenv("DEEPSEEK_API_KEY"))
                .build()));

        // 4. 设为默认模型，并让配置生效
        rt.declaration().getAgentConfig().setDefaultModel("deepseek-v3");
        rt.declaration().applyAllInstance();

        // 5. 组装一次对话
        String historyId = IdGen.uuid();         // 32 位无连字符
        AgentContextHolder holder = AgentContextHolder.builder()
                .userId("u1")
                .historyId(historyId)
                .modelAlias("deepseek-v3")
                .prompt("你是一个严谨的助手")
                .workspacePath("D:/workspace/demo")
                .vfsId(historyId)
                .build();

        // 6. 开始对话
        AutoAgent agent = new AutoAgent(holder, "demo-agent");
        String answer = agent.chat("你好，用一句话介绍你自己");
        System.out.println(answer);
    }
}

加一点：让 AI 会读文件

AutoAgent 默认不挂任何工具。挂上只读工具集，它就能看文件了：

AutoAgent agent = new AutoAgent(holder, "demo-agent")
        .mountToolsIfAbsent(AutoAgent.readOnlyTools().toArray(new String[0]));

mountToolsIfAbsent 是幂等的：已经挂过的工具不会重复挂。

再加一点：流式输出

chatStream 是异步的，返回 CountDownLatch，要等它。事件通过 EventCenter 出来：

import net.itzq.mira.modules.ai.agent.event.DefaultEventListener;
import net.itzq.mira.modules.ai.agent.event.EventCenter;
import net.itzq.mira.modules.ai.agent.event.type.ErrorEvent;
import net.itzq.mira.modules.ai.entity.chat.AnsResponse;

// 一条会话一条事件通道
EventCenter eventCenter = new EventCenter();
eventCenter.register(new DefaultEventListener() {
    @Override
    public void sseEmitterSend(Object response) {
        if (response instanceof AnsResponse) {
            AnsResponse res = (AnsResponse) response;
            // 按 type 分流渲染：ChatReasonContent 思考、ChatContent 正文……
            System.out.println(res.getType() + " -> " + res.getAnswer());
        }
    }

    @Override
    public void onError(ErrorEvent event) {
        event.getThrowable().printStackTrace();
    }
});
holder.setEventCenter(eventCenter);

agent.chatStream("你好，用一句话介绍你自己").await();   // 等到本轮结束

跑起来会看到什么

启动时控制台会打印：

【KernelRuntime】已启动: name=my-first-app, tools=17, models=1
【KernelRuntime】默认运行时已安装: name=my-first-app, dataDir=D:/my-app/data

同步 chat：最后打印一行模型回答的文本。

流式 chatStream：会连续打印很多行，ChatReasonContent 是思考过程，ChatContent 是正文，最后一条是 ChatEnd。

如果挂了工具，中间还会穿插 CallToolBegin / CallToolEnd。

换个场景怎么改

目标	改哪里
换成别的厂商模型	改 ModelApiConfig 的 apiHost / apiEndpoint / apiModelName / apiKey
换模型不解绑代码	新加一个 ModelApiConfig，对话时改 holder 的 modelAlias
让 AI 改文件、执行命令	换成挂全量工具：agent.mountFullCodeTools()
让 AI 在指定项目目录里干活	改 holder 的 workspacePath
给 AI 上传文件	用 vfsId 对应的附件包写文件，见会话附件（VFS）
要永久记住历史	挂持久化，见消息持久化
换系统提示词	改 holder 的 prompt，或改配置快照里的提示词

注意事项（常见报错排查）

现象	原因	修法
tools=..., models=0，模型列表为空	写完配置没调 applyAllInstance()；或 installDefault 晚于第一次读配置	写配置后调 rt.declaration().applyAllInstance()；把 installDefault 放到最前面
报错 VFS 未初始化：dataDir 为空	没装默认运行时，或运行时的 dataDir 为空	启动时 installDefault(rt) 且给 dataDir
报错说 sessionId 必须是 32 位	用了带连字符的 UUID.randomUUID()	用 IdGen.uuid()
模型网关报 duplicate names	工具白名单里有重复	用 mountToolsIfAbsent，自己拼白名单时先去重
工具调用参数全是 null	编译没保留参数名	编译插件保留 <parameters>true</parameters>
流式调用像没反应	忘了等 CountDownLatch	agent.chatStream(...).await()
apiKey 为 null 请求被拒	环境变量没读到	确认 System.getenv("DEEPSEEK_API_KEY") 有值

相关：整体结构、内核运行时装配、基础对话

流程配错了一个模型名，不希望跑到一半才出错。ExecutionResolver 就是那个"执行前的检查站"：把节点的需求（NodeBlueprint）和这一次的供给（Invocation）对一遍，说明模型在不在、工具包能不能解析、必需参数齐不齐，并给出可以直接拿去执行的模型别名和工具白名单。

场景

流程定义由运维在界面上拼，很容易把模型别名写错，或者引用一个已经被删掉的工具包。如果这些错误要等模型调用返回 404 才发现，用户体验非常糟。目标是在执行前先跑一次校验：错了就说清楚错在哪，对了就直接拿到"用哪个模型、带哪些工具"。

resolve(...) 的执行流程

ExecutionResolver.resolve(node, invocation, toolResolver, declaration)

四个参数：

参数	含义
node	节点的需求清单（NodeBlueprint），可传 null = 当成空节点
invocation	这一次的调用参数（Invocation），可传 null = 当成空调用
toolResolver	实现的工具包解析回调，可传 null（此时无法解析工具包，只在报告里记警告）
declaration	用哪份配置快照来校验模型（可传 null → 回落默认运行时）

它依次做三件事：

refs.model → 值不为空就查配置快照的 models 里有没有这个别名；值为空就回落配置快照的默认模型；两者都没有则记一条 model 缺失。

refs.toolkits → 值是非空的 List 时，交给 ToolResolver 解析成工具名集合；解析抛异常则记一条 toolkit 缺失；toolResolver 传了 null 则记一条警告。

requires → 逐个检查 invocation 里有没有这个键（invocation.question 和 question 两种写法都认）；缺了记一条 invocation 缺失。refs 里 @invocation.<key> 形态的间接引用如果取不到值，同样记 invocation 缺失。

Resolution 的产出

方法	作用
canExecute()	能不能执行。等价于报告 isPass()：无致命、无缺失
getReport()	校验报告 ValidationReport，含 missing / warnings
getModelAlias()	解析后的模型别名（可能来自节点，也可能是回落的默认模型）
getToolWhitelist()	解析后的工具名集合，内容取决于传入的 ToolResolver
getResolvedRefs()	全部引用解析后的结果，自定义引用名也在这里

失败为什么不猜

校验报告绝不静默补默认值。具体来说：

节点写了一个不存在的模型别名 → 记缺失，不让执行。不会偷偷换成一个"看起来差不多"的模型。

工具包解析不出来 → 记缺失。不会给一个空工具集让节点"裸奔"。

必需参数没给 → 记缺失。

宁可挡住，也不猜。因为流程配错时，"猜一个相近的模型""给个空工具集"都会让错误更难排查。

ToolResolver 也要遵守同样的原则：

public interface ToolResolver {
    Set<String> resolve(List<?> kitIds);
}

它把"工具包 id"解析成"工具名集合"。解析不出来必须报错（抛异常），而不是返回空集合或 null。 返回空集合会被当成"这个工具包就是空的"，于是流程带着一个错误的假设继续跑；抛异常则会被 resolve 记成缺失项，正大光明地挡下来。

最小可用代码

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.runtime.KernelRuntime;
import net.itzq.mira.modules.config.AgentConfig;
import net.itzq.mira.modules.config.GlobalConfigManager;
import net.itzq.mira.modules.config.ValidationReport;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.client.config.ModelApiConfig;
import net.itzq.mira.modules.ai.orchestration.ExecutionResolver;
import net.itzq.mira.modules.ai.orchestration.ExecutionResolver.ToolResolver;
import net.itzq.mira.modules.ai.orchestration.Invocation;
import net.itzq.mira.modules.ai.orchestration.NodeBlueprint;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class ExecutionResolverDemo {

    // 工具包 id → 工具名集合；真实场景里来自数据库或配置
    private static final Map<String, Set<String>> TOOLKITS = new HashMap<String, Set<String>>();
    static {
        Set<String> tools = new LinkedHashSet<String>();
        tools.add("Read");
        tools.add("Grep");
        TOOLKITS.put("report-tools", tools);
    }

    // 实现的工具包解析回调：换不到就抛异常（fail-closed）
    private static final ToolResolver TOOL_RESOLVER = new ToolResolver() {
        @Override
        public Set<String> resolve(List<?> kitIds) {
            Set<String> names = new LinkedHashSet<String>();
            for (Object id : kitIds) {
                Set<String> one = TOOLKITS.get(String.valueOf(id));
                if (one == null) {
                    throw new IllegalStateException("工具包不存在: " + id);
                }
                names.addAll(one);
            }
            return names;
        }
    };

    public static void main(String[] args) {
        KernelRuntime rt = KernelRuntime.builder()
                .name("resolve-demo")
                .dataDir("D:/my-app/data")
                .build();
        KernelRuntime.installDefault(rt);
        rt.start();

        GlobalConfigManager decl = rt.declaration();
        ModelApiConfig model = ModelApiConfig.builder()
                .alias("deepseek-v3")
                .providerName("deepseek")
                .apiModelName("deepseek-chat")
                .apiHost("https://api.deepseek.com")
                .apiEndpoint("/v1/chat/completions")
                .apiKey(System.getenv("DEEPSEEK_API_KEY"))
                .build();
        decl.setModels(new ArrayList<ModelApiConfig>(Arrays.asList(model)));
        AgentConfig agentConfig = new AgentConfig();
        agentConfig.setDefaultModel("deepseek-v3");
        decl.setAgentConfig(agentConfig);
        decl.applyAllInstance();

        Map<String, String> refKeyMap = new HashMap<String, String>();
        refKeyMap.put("model", "model_id");
        refKeyMap.put("toolkits", "toolkits");

        Invocation invocation = Invocation.builder()
                .question("把本周数据总结成一份周报")
                .historyId(IdGen.uuid())
                .build();

        // ============ 情况一：模型别名写错了 ============
        Map<String, Object> badNode = new HashMap<String, Object>();
        badNode.put("model_id", "deepseek-vX");                 // 不存在
        badNode.put("toolkits", Arrays.asList("report-tools"));
        badNode.put("prompt", "把下面的数据总结成一份周报");

        NodeBlueprint badBp = NodeBlueprint.from(
                "ai-chat-node", badNode, Arrays.asList("question"), refKeyMap);

        ExecutionResolver.Resolution bad =
                ExecutionResolver.resolve(badBp, invocation, TOOL_RESOLVER, decl);
        if (!bad.canExecute()) {
            System.out.println(bad.getReport().summary());
            for (ValidationReport.Missing m : bad.getReport().getMissing()) {
                System.out.println("缺少: kind=" + m.getKind()
                        + ", ref=" + m.getRef() + ", detail=" + m.getDetail());
            }
            System.out.println("--- 修正模型别名后重试 ---");
        }

        // ============ 情况二：改对了，取出模型与工具白名单执行 ============
        Map<String, Object> node = new HashMap<String, Object>();
        node.put("model_id", "deepseek-v3");
        node.put("toolkits", Arrays.asList("report-tools"));
        node.put("prompt", "把下面的数据总结成一份周报");

        NodeBlueprint bp = NodeBlueprint.from(
                "ai-chat-node", node, Arrays.asList("question"), refKeyMap);

        ExecutionResolver.Resolution resolution =
                ExecutionResolver.resolve(bp, invocation, TOOL_RESOLVER, decl);
        if (!resolution.canExecute()) {
            System.out.println(resolution.getReport().summary());
            rt.close();
            return;
        }

        String modelAlias = resolution.getModelAlias();
        Set<String> toolWhitelist = resolution.getToolWhitelist();
        System.out.println("校验通过：模型 = " + modelAlias + ", 工具 = " + toolWhitelist);

        AgentContextHolder holder = AgentContextHolder.builder()
                .runtime(rt)
                .userId("u1")
                .historyId(IdGen.uuid())
                .modelAlias(modelAlias)
                .prompt((String) node.get("prompt"))
                .build();
        holder.addTools(toolWhitelist.toArray(new String[0]));

        String output = new AutoAgent(holder).chat(invocation.getQuestion());
        System.out.println("节点输出 = " + output);

        rt.close();
    }
}

