import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.runtime.KernelRuntime;
import net.itzq.mira.modules.config.AgentConfig;
import net.itzq.mira.modules.config.GlobalConfigManager;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.client.config.ModelApiConfig;
import net.itzq.mira.modules.ai.orchestration.Invocation;

import java.util.ArrayList;
import java.util.Arrays;

public class InvocationDemo {

    public static void main(String[] args) {
        KernelRuntime rt = KernelRuntime.builder()
                .name("invocation-demo")
                .dataDir("D:/my-app/data")
                .build();
        KernelRuntime.installDefault(rt);
        rt.start();

        // 注册一个模型（流程/调用参数都按别名引用它）
        GlobalConfigManager decl = rt.declaration();
        ModelApiConfig model = ModelApiConfig.builder()
                .alias("deepseek-v3")
                .providerName("deepseek")
                .apiModelName("deepseek-chat")
                .apiHost("https://api.deepseek.com")
                .apiEndpoint("/v1/chat/completions")
                .apiKey(System.getenv("DEEPSEEK_API_KEY"))
                .build();
        decl.setModels(new ArrayList<ModelApiConfig>(Arrays.asList(model)));
        AgentConfig agentConfig = new AgentConfig();
        agentConfig.setDefaultModel("deepseek-v3");
        decl.setAgentConfig(agentConfig);
        decl.applyAllInstance();

        // 1) 构造调用参数：这一次要什么
        Invocation invocation = Invocation.builder()
                .question("帮我看看这份合同有没有风险点")
                .workspacePath("D:/workspace/contract-review")
                .modelAlias("deepseek-v3")
                .enableThinking(Boolean.FALSE)
                .historyId(IdGen.uuid())
                .extra("chatMode", "review")
                .extra("tenantId", "t-001")
                .build();

        // 2) 把参数填进执行现场
        AgentContextHolder holder = AgentContextHolder.builder()
                .runtime(rt)
                .userId("u1")
                .historyId(invocation.getHistoryId())
                .modelAlias(invocation.getModelAlias())
                .workspacePath(invocation.getWorkspacePath())
                .prompt("你是一个严谨的合同审阅助手")
                .build();

        // 业务扩展键顺手转成现场变量，供工具或后续节点使用
        Object tenantId = invocation.get("tenantId");
        if (tenantId != null) {
            holder.getGlobalVariables().put("tenantId", String.valueOf(tenantId));
        }

        // 3) 开跑
        if (!invocation.has("question")) {
            System.out.println("缺少 question，无法执行");
            rt.close();
            return;
        }
        String answer = new AutoAgent(holder).chat(invocation.getQuestion());
        System.out.println("回答 = " + answer);

        rt.close();
    }
}

跑起来会看到什么

控制台打印 回答 = 这份合同有 3 个风险点：...。

如果 question 传空串，invocation.has("question") 为 false，会打印 缺少 question，无法执行，不会去调模型。

holder.getGlobalVariables() 里能看到 tenantId=t-001，供后面的工具/节点读取。

换个场景怎么改

加自定义业务参数（extra）

extra 是给业务用的自由袋，内核不校验它的内容，加多少键都行：

Invocation invocation = Invocation.builder()
        .question("生成周报")
        .extra("tenantId", "t-001")
        .extra("locale", "zh-CN")
        .extra("maxTokens", 2000)
        .build();

// 读出来
String tenant = String.valueOf(invocation.get("tenantId"));

想加的东西	放哪	读法
一次性的业务参数	extra	invocation.get("键")
执行时要给工具看的变量	AgentContextHolder.tempVariables	holder.getTempVariables()
整个会话共享的变量	AgentContextHolder.globalVariables	holder.getGlobalVariables()

其他常见改法

目标	改哪儿
这次换成别的模型	.modelAlias("local-vllm")
这次打开思考	.enableThinking(Boolean.TRUE)
这次不带记忆	不写 historyId（即用即释放）
这次要带图片	.image("data:image/png;base64,...")，并且用 agent.chatStream(question, invocation.getImages()) 发送

使用要点

historyId 为空：表示不挂持久化，跑完即弃；需要连续对话时须为其指定一个 id。

question 通常必填：编排节点的 requires 经常包含它，缺了会被校验拦下。

Invocation 不序列化进配置：其 toMap() 用于落盘会话数据，但那是会话数据的形态，不是配置。

has 的判空规则：空串和空集合都算"没有"，所以传 "" 和没传效果一样。

相关：编排：让 AI 按流程跑、执行前先校验、停止与续跑

流程定义里的一个节点，写的是"该节点有哪些数据"：模型 id 叫 model_id、工具包叫 toolkits。可内核不认识这些长得各不相同的键名，它只认"需要一个模型别名""需要几个工具包"。把节点数据翻译成内核能理解的需求清单，用的就是 NodeBlueprint（节点配置声明）。

场景

流程里每个节点的数据形状都不一样：取数节点有 endpoint、maxRows；AI 节点有 model_id、toolkits、prompt。不希望由内核去猜每种节点的字段名，只在装配的那一步明确告知："model_id 这个字段，就是所需的模型引用。"这样节点类型爱怎么定键名就怎么定，内核只管照映射取。

NodeBlueprint 的结构

它描述一个节点在执行前需要什么，由三个部分组成：

部分	类型	含义
requires	List<String>	执行必须的调用参数键。比如 ["question"]，缺了就不该跑
refs	Map<String, Object>	按名字引用配置快照里的资源。内核约定两个名字：model 和 toolkits
config	Map<String, Object>	节点私有配置，形状由节点类型自己定

外加一个 type：节点类型名，比如 ai-chat-node。

关于 refs 还有两点：

键是内核认识的名字（model / toolkits，也可放入别的自定义名）；值通常是一个别名或 id 列表。

值可以是 @invocation.<key> 形态，表示"这个引用不在节点里写死，运行时从调用参数里取"。比如 refs.model = "@invocation.modelAlias"，那么这次用哪个模型由调用参数决定。

NodeBlueprint.from(...) 的四个参数

NodeBlueprint.from(String nodeType, Map<String, Object> nodeData,
                   List<String> requires, Map<String, String> refKeyMap)

参数	含义
nodeType	节点类型名，写进 type
nodeData	节点私有配置原文，直接成为 config
requires	协议里的必需调用参数键清单，直接成为 requires
refKeyMap	引用键名 → 节点数据里的字段名的映射，用来从 nodeData 里抓出 refs

refKeyMap 的映射方向是：键为内核认识的名字，值为 nodeData 里实际存的字段名。

比如 refKeyMap = {"model": "model_id", "toolkits": "toolkits"}，含义是：

内核要 model 这个引用 → 去 nodeData 里读 model_id 字段；

内核要 toolkits 这个引用 → 去 nodeData 里读 toolkits 字段。

from 的行为细节：

config 就是 nodeData 本身（不是拷贝）。

requires 会被复制一份，之后改原列表不会影响已装配的结果。

只有当 nodeData 里对应字段不为 null 时，才会写进 refs；字段缺失就不产生这个引用。

装好之后还能手工补引用：bp.getRefs().put("model", "local-vllm")。

最小可用代码

import net.itzq.mira.modules.ai.orchestration.NodeBlueprint;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class NodeBlueprintDemo {

    public static void main(String[] args) {
        // 流程定义里一个 AI 节点的原始数据
        Map<String, Object> nodeData = new HashMap<String, Object>();
        nodeData.put("model_id", "deepseek-v3");
        nodeData.put("toolkits", new ArrayList<String>(Arrays.asList("report-tools")));
        nodeData.put("prompt", "把下面的数据总结成一份周报");
        nodeData.put("maxRows", 200);

        // 协议元数据：这个节点必须要有 question
        List<String> requires = Arrays.asList("question");

        // 引用映射：内核的 model ← 节点里的 model_id；内核的 toolkits ← 节点里的 toolkits
        Map<String, String> refKeyMap = new HashMap<String, String>();
        refKeyMap.put("model", "model_id");
        refKeyMap.put("toolkits", "toolkits");

        NodeBlueprint bp = NodeBlueprint.from("ai-chat-node", nodeData, requires, refKeyMap);

        System.out.println("节点类型 = " + bp.getType());
        System.out.println("必需参数 = " + bp.getRequires());
        System.out.println("引用     = " + bp.getRefs());
        System.out.println("私有配置 = " + bp.getConfig());
    }
}

跑起来会看到什么

节点类型 = ai-chat-node
必需参数 = [question]
引用     = {model=deepseek-v3, toolkits=[report-tools]}
私有配置 = {prompt=把下面的数据总结成一份周报, model_id=deepseek-v3, toolkits=[report-tools], maxRows=200}

refs 里出现内核认识的 model 和 toolkits，值是节点里 model_id、toolkits 的真实内容；config 保留节点的全部原始字段（包括内核不关心的 maxRows）。

换个场景怎么改

一个节点要用两个模型

内核的 ExecutionResolver 只对名字恰好叫 model 的引用做模型存在性校验。使用两个模型时，为第二个模型指定一个自定义引用名并放入 refs：

NodeBlueprint bp = NodeBlueprint.from("ai-chat-node", nodeData, requires, refKeyMap);

// 第二个模型：换个自定义引用名
bp.getRefs().put("refinerModel", "gpt-4o-mini");

这个 refinerModel 不在内核约定名单里，它会原样出现在解析结果的 resolvedRefs 里，不会被自动校验。要校验它就自己来：

boolean exists = net.itzq.mira.modules.ai.orchestration.ExecutionResolver
        .hasModel("gpt-4o-mini");

用工具包 id 列表怎么写

工具包引用的名字必须是 toolkits，值是一个 List（id 列表），内核才会去走 ToolResolver 解析：

// refKeyMap 里把内核的 toolkits 映射到节点字段
refKeyMap.put("toolkits", "toolkit_ids");   // 节点里字段叫 toolkit_ids

// 于是 nodeData 里这样写：
// nodeData.put("toolkit_ids", Arrays.asList("report-tools", "db-tools"));

解析出来的是一组工具名（不是 id），见执行前先校验。

其他常见改法

目标	改哪儿
模型运行时才定	refs.model 放 "@invocation.modelAlias"
节点必须收到某个业务参数	往 requires 里加键名
节点数据字段改叫别的名字	只改 refKeyMap 的值，别动键

使用要点

refKeyMap 的映射方向：键为内核认识的名字（model / toolkits），值为节点里的字段名，二者不可颠倒。

字段缺失的行为：字段缺失不会报错，也不会产生对应引用；nodeData 里没有 model_id 时，refs 里就没有 model，后续校验按"未指定模型"处理（可能回落默认模型，也可能记缺失）。

config 与 nodeData 同源：二者是同一个对象，装配后修改 nodeData 会同步反映到 config。

自定义引用名不自动校验：内核只处理 model 和 toolkits 两个约定名。

相关：调用参数：这一次怎么跑、执行前先校验、插件配置项

除了一问一答，也常需要把多个 AI 步骤按流程串联。本篇说明流程由哪三块拼成、内核提供哪些拼装件，以及哪一部分需由调用方编写。

场景

以每周自动生成周报为例：先从内部接口拉取本周数据，交给大模型总结，判断总结是否为空，最后输出。每个节点要做的事不同，用到的模型、工具也不同。目标是把它描述成一张流程图，再由执行器按图运行，而不是把逻辑硬编码成一长串调用。

三样东西的分工

一张能跑的流程，由三份东西拼成，各自回答一个问题：

东西	回答的问题	内容
配置快照	这个系统有什么	有哪些模型、哪些工具包、系统提示词。全局共享，一份就够
流程定义	节点怎么连、每个节点用什么	节点清单、连线、每个节点的配置数据（用哪个模型、挂哪些工具包）
调用参数	这一次跑的是什么	这一次的输入是什么、挂哪个会话

三者关系：流程定义按名字去配置快照里取资源，调用参数在运行时补给流程。流程里的节点写 model_id: "deepseek-v3"，这个别名必须能在配置快照的 models 里找到；节点写 question 为必需输入，这个值来自调用参数。对不上就跑不了——这正是下一节"先校验"要解决的问题。

一份最小的流程定义

流程定义不是内核规定的格式，它就是应用自身的数据模型。最小形态是"节点 + 连线 + 节点配置"：

{
  "id": "weekly-report",
  "nodes": [
    {
      "id": "start",
      "type": "start-node",
      "data": {}
    },
    {
      "id": "fetch",
      "type": "data-fetch-node",
      "data": {
        "endpoint": "https://internal.example.com/weekly",
        "maxRows": 200
      }
    },
    {
      "id": "summarize",
      "type": "ai-chat-node",
      "data": {
        "model_id": "deepseek-v3",
        "toolkits": ["report-tools"],
        "prompt": "把下面的数据总结成一份周报"
      }
    },
    {
      "id": "check",
      "type": "condition-node",
      "data": {
        "expression": "output.length > 0"
      }
    },
    {
      "id": "end",
      "type": "end-node",
      "data": {}
    }
  ],
  "edges": [
    { "from": "start", "to": "fetch" },
    { "from": "fetch", "to": "summarize" },
    { "from": "summarize", "to": "check" },
    { "from": "check", "to": "end", "when": "true" }
  ]
}

读法：

nodes[].type 是节点类型，决定"谁来执行这个节点"。

nodes[].data 是节点私有配置，形状由节点类型自己定。比如 AI 节点里 model_id 是模型别名、toolkits 是工具包 id 列表。

edges 是连线，决定执行顺序；带条件的连线（when）决定分支走向。

上面 model_id、toolkits 这些键名是这套流程自己的约定。内核不认识 model_id，它只认识"需要一个模型别名"这件事——把外部键名映射成内核能理解的引用，是下一篇文章要讲的装配动作。

内核提供哪几块拼装件

三块，分别对应上文的三份东西：

拼装件	对应	作用
Invocation	调用参数	描述"这一次怎么跑"：问题、图片、工作空间、模型覆盖、思考开关、会话 id、扩展键
NodeBlueprint	流程定义里的一个节点	把一个节点翻译成内核能理解的"需求清单"：要哪些调用参数、按名字引用哪些资源、节点私有配置是什么
ExecutionResolver	校验	把"需求"和"供给"对上：模型别名在不在、工具包能不能解析、必需参数齐不齐，产出可执行结论

执行器主循环需由调用方编写

内核不管调度。 它不会代为遍历节点、不会判断分支、不会决定下一个是谁、也不会发"节点开始/结束"的事件。内核只负责"接收一个节点 + 这次的调用参数，说明这个节点能不能跑、跑起来用哪个模型和哪些工具"。

所以一个完整的编排执行器基于内核搭建，由以下部件组织，每个部件标注了其对应的内核 API：

#	部件	做什么	对应内核 API
1	流程数据模型	节点 + 连线 + 每个节点的配置数据	自定义的 POJO / JSON，内核无对应
2	执行器主循环	按连线取下一个节点执行，执行前后各发一个事件	自己写；事件用 EventCenter + AnsResponse
3	节点执行器注册表	按节点类型找到"谁来执行"	自己写（一个 Map<类型, 执行器>）
4	插件式节点	一个节点类型 = 一份清单（类型名、必填输入、引用的配置项）+ 一个执行器	设置值读 GlobalConfigManager.pluginSetting(...)；设置项定义用 PluginSettingDef
5	节点里跑 AI	先校验再执行，工具包 id 换成工具名集合	NodeBlueprint.from(...) + ExecutionResolver.resolve(...) + 通过实现 ToolResolver
6	每个节点自己的记忆	每个节点一个会话 id，挂同一个持久化实现	IdGen.uuid() 生成会话 id；AgentContextHolder.historyId
7	输出统一走事件	决定哪些事件透传、哪些自己收尾	EventCenter + DefaultEventListener

第 5 项是最核心的，也是唯一需要"内核与调用方各写一半"的地方。

最小可用代码

以一个 AI 节点为例：装配 → 校验 → 执行。把这套动作放进上面第 2 项的循环里，就是完整的执行器。

import net.itzq.mira.core.utils.IdGen;
import net.itzq.mira.modules.runtime.KernelRuntime;
import net.itzq.mira.modules.config.AgentConfig;
import net.itzq.mira.modules.config.GlobalConfigManager;
import net.itzq.mira.modules.ai.agent.AgentContextHolder;
import net.itzq.mira.modules.ai.agent.AutoAgent;
import net.itzq.mira.modules.ai.client.config.ModelApiConfig;
import net.itzq.mira.modules.ai.orchestration.ExecutionResolver;
import net.itzq.mira.modules.ai.orchestration.Invocation;
import net.itzq.mira.modules.ai.orchestration.NodeBlueprint;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class OneNodeDemo {

    public static void main(String[] args) {
        KernelRuntime rt = KernelRuntime.builder()
                .name("orchestration-demo")
                .dataDir("D:/my-app/data")
                .build();
        KernelRuntime.installDefault(rt);
        rt.start();

        // 配置快照：注册一个模型（流程定义要按别名引用它）
        GlobalConfigManager decl = rt.declaration();
        ModelApiConfig model = ModelApiConfig.builder()
                .alias("deepseek-v3")
                .providerName("deepseek")
                .apiModelName("deepseek-chat")
                .apiHost("https://api.deepseek.com")
                .apiEndpoint("/v1/chat/completions")
                .apiKey(System.getenv("DEEPSEEK_API_KEY"))
                .build();
        decl.setModels(new ArrayList<ModelApiConfig>(Arrays.asList(model)));
        AgentConfig agentConfig = new AgentConfig();
        agentConfig.setDefaultModel("deepseek-v3");
        decl.setAgentConfig(agentConfig);
        decl.applyAllInstance();

        // 流程定义里的一个节点（实际从数据模型读）
        Map<String, Object> nodeData = new HashMap<String, Object>();
        nodeData.put("model_id", "deepseek-v3");
        nodeData.put("prompt", "把下面的数据总结成一份周报");

        // 装配成内核能理解的"需求清单"
        NodeBlueprint bp = NodeBlueprint.from(
                "ai-chat-node",
                nodeData,
                Arrays.asList("question"),
                Collections.singletonMap("model", "model_id"));

        // 调用参数：这一次跑的是什么
        Invocation invocation = Invocation.builder()
                .question("本周进展：完成登录改造、修复 3 个缺陷")
                .historyId(IdGen.uuid())
                .build();

        // 先校验：模型在不在、必需参数齐不齐
        ExecutionResolver.Resolution resolution =
                ExecutionResolver.resolve(bp, invocation, null, decl);
        if (!resolution.canExecute()) {
            System.out.println(resolution.getReport().summary());
            rt.close();
            return;
        }

        // 校验通过，执行这个节点
        AgentContextHolder holder = AgentContextHolder.builder()
                .runtime(rt)
                .userId("u1")
                .historyId(IdGen.uuid())
                .modelAlias(resolution.getModelAlias())
                .prompt((String) nodeData.get("prompt"))
                .build();
        holder.addTools(resolution.getToolWhitelist().toArray(new String[0]));

        String output = new AutoAgent(holder).chat(invocation.getQuestion());
        System.out.println("节点输出 = " + output);

        rt.close();
    }
}

跑起来会看到什么

模型注册后，控制台打印 节点输出 = 本周周报：...。

如果故意把 nodeData 里的 model_id 改成 deepseek-vX（一个没注册的别名），校验会拦住，打印类似：

[INCOMPLETE] missing=1, warnings=0
  - model: deepseek-vX (配置快照（declaration.models）中不存在该 alias)

如果故意不传 question，打印里会出现 invocation: question 的缺失项。

预校验的意义在于：配置错误在执行前就能被发现，而不是执行到中途才失败。

换个场景怎么改

串行流程 vs 并行分支

目标	主循环怎么改
串行	维护一个"当前节点 id"，按 edges 取下一个，一个接一个
并行分支	一个节点有多条出边时，把下游节点提交到内核自带线程池并发跑（ThreadPoolUtil.getExecutorService()，无需自行创建线程池），用计数器 / 屏障等它们汇合
条件分支	读连线上的 when 条件，只走命中的那条出边
人工审批节点	见下

加人工审批节点

做法和停止与续跑是同一套机制：

节点执行到"审批"时，向调用方发一个事件（AnsResponse）说明"等你决定"。

不在循环里阻塞，直接结束这一轮，把流程状态（当前节点、已产出）存起来。

外部做出决定后，带着决定再次进入循环，从这个节点继续往下。

审批节点本身不需要调模型，所以它不碰 ExecutionResolver；只有真正要跑 AI 的节点才走"装配 → 校验 → 执行"那三步。

约束

内核不提供调度：没有现成的"运行流程图"方法，主循环、分支、并发均需自行实现。

流程定义里的别名需先在配置快照里存在：先 applyAllInstance() 把模型 / 工具注册好，再跑节点。

每个节点用自己的会话 id：想"每个节点有自己的记忆"，就给每个节点单独生成一个 historyId。

相关：调用参数：这一次怎么跑、节点配置：这个节点需要什么、执行前先校验

内核自带的一批小工具类，按用途分组说明。

提示词模板（PromptLoader + PropsMap）

系统提示词包含动态片段（如"本次可用的技能清单"）时，采用模板加变量的写法。

方法	用途
PromptLoader.readFileString(path)	读取模板文本（先找文件，再找 classpath 资源）
PromptLoader.createTemplate(content)	把文本变成模板
PromptLoader.processTemplate(template, params)	用变量渲染模板
PropsMap.put(key, value)	放入模板变量

import net.itzq.mira.core.utils.PromptLoader;
import net.itzq.mira.core.utils.PropsMap;

String templateText = PromptLoader.readFileString("prompt/agent_system.md");
PropsMap params = new PropsMap();
params.put("skills", "- 周报生成：根据本周记录生成周报");
params.put("skillCount", "1");

String prompt = PromptLoader.processTemplate(
        PromptLoader.createTemplate(templateText), params);
holder.setPrompt(prompt);   // 写回上下文

变量为 null 时，PromptLoader.prompt(path, params) 会把它替换成空串，避免模板渲染报错。

相关：上层应用接入清单、配置中心
